+
+    private void initializeNotificationSlots(final VideoPlayerImpl player) {
+        for (int i = 0; i < 5; ++i) {
+            notificationSlots[i] = player.sharedPreferences.getInt(
+                    player.context.getString(NotificationConstants.SLOT_PREF_KEYS[i]),
